int sub_02005328(enum SoundHeapState state) {
    int *param;
    SoundSystem *soundSys = GetSoundDataPointer();

    if (state >= SOUND_HEAP_STATE_COUNT) {
        ((0) ? (void)0 : GF_AssertFail());
        param = GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_HEAP_STATE_BGM);
        return *param;
    }

    switch (state) {
    case SOUND_HEAP_STATE_EMPTY:
        param = GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_HEAP_STATE_EMPTY);
        break;
    case SOUND_HEAP_STATE_PERSISTENT:
        param = GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_HEAP_STATE_PERSISTENT);
        break;
    case SOUND_HEAP_STATE_BGM_BANK:
        param = GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_HEAP_STATE_BGM_BANK);
        break;
    case SOUND_HEAP_STATE_SFX:
        param = GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_HEAP_STATE_SFX);
        break;
    case SOUND_HEAP_STATE_BGM:
        param = GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_HEAP_STATE_BGM);
        break;
    case SOUND_HEAP_STATE_SUB_SFX:
        param = GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_HEAP_STATE_SUB_SFX);
        break;
    case SOUND_HEAP_STATE_FANFARE:
        param = GF_SdatGetAttrPtr(SOUND_SYSTEM_PARAM_HEAP_STATE_FANFARE);
        break;
    }

    return *param;
}
